import {resourceError} from './resource-error.mjs';
import React from 'react';import {useStoryLinks} from './useStoryLinks.js';
export function MaterialStoryLinks({call,novelId,nodeId,tick,onStoryCard}){const r=useStoryLinks(call,novelId,tick);if(!r.value)return <div><p role={r.error?'alert':'status'}>{r.error?resourceError(r.error):'读取剧情关联…'}</p>{r.error&&<button type="button" onClick={r.retry}>重试读取剧情关联</button>}</div>;const cards=r.value.cards.filter(c=>c.cast?.some(p=>p.nodeId===nodeId));return <section className="profile-activity">{r.error&&<p role="alert">{resourceError(r.error)}<button type="button" onClick={r.retry}>重试</button></p>}<h4>关联剧情卡 · {cards.length}</h4><p className="profile-caption">参与计划不自动记为正文出场。</p>{cards.map(c=><article className="profile-event-card" key={c.id}><button onClick={()=>onStoryCard?.(c.id)}>{c.title}</button><small>{c.storyDateText||'日期未定'} · {c.cast.find(p=>p.nodeId===nodeId)?.kind==='mention'?'仅提及':'计划参与'}</small>{c.summary&&<p>{c.summary}</p>}</article>)}</section>;}
